""""
Compare the 'Source' and 'Source2' sheets and write the difference to the
'Result' sheet (A2:A8) of output.xlsx.

Rules:
  * Values that appear in 'Source' but NOT in 'Source2' -> copied to 'Result'.
  * Exception: the value 2 is only included when it is present in BOTH
    'Source' and 'Source2' (and then only once).
  * Duplicated values are written only once.
"""

import openpyxl


def canonical(value):
    """Normalize a cell value so comparisons (e.g. 2 vs 2.0 vs '2') work."""
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return float(value)
    return str(value).strip()


def is_two(value):
    """True if the cell value represents the number 2."""
    try:
        c = canonical(value)
        return c is not None and float(c) == 2.0
    except (TypeError, ValueError):
        return False


def read_column(ws, col=1, start_row=2):
    """Read all non-empty cell values from a column, starting at start_row."""
    values = []
    for r in range(start_row, ws.max_row + 1):
        v = ws.cell(row=r, column=col).value
        if v is not None:
            values.append(v)
    return values


def main():
    # Load the provided input workbook (output.xlsx is a copy of it)
    wb = openpyxl.load_workbook('input.xlsx')

    source_values = read_column(wb['Source'])
    source2_set = {canonical(v) for v in read_column(wb['Source2'])}

    result = []
    seen = set()
    for v in source_values:
        c = canonical(v)
        if c in seen:                      # write each value only once
            continue
        if is_two(v):
            # '2' goes into Result only when it exists in BOTH sources
            if c in source2_set:
                result.append(v)
                seen.add(c)
        elif c not in source2_set:
            # regular rule: in Source but not in Source2
            result.append(v)
            seen.add(c)

    # Get or create the Result sheet
    if 'Result' in wb.sheetnames:
        ws_res = wb['Result']
    else:
        ws_res = wb.create_sheet('Result')

    # Write the answer into Result!A2:A8 (blank out unused cells)
    for r in range(2, 9):
        ws_res.cell(row=r, column=1).value = result[r - 2] if r - 2 < len(result) else None

    wb.save('output.xlsx')
    print('Result values written to Result!A2:A8:', result)


if __name__ == '__main__':
    main()"
